export interface SimpleIcon {
  title: string;
  slug: string;
  hex: string;
  path: string;
  viewBox?: string;
}

function createIcon(title: string, slug: string, hex: string, path: string, viewBox = "0 0 24 24"): SimpleIcon {
  return { title, slug, hex, path, viewBox };
}

